@router.post({{path}}, response_model=ChildRead, status_code=201)
def create_child(parent_id: int, data: ChildCreate, db: Annotated[Session, Depends(session_provider)]) -> Child:
    """Create child."""
    require_parent(db, parent_id)
    row = Child({{foreign_key}}=parent_id, **model_values(data))
    db.add(row)
    try:
        db.commit()
    except IntegrityError as exc:
        integrity_failure(db, exc, True)
    db.refresh(row)
    return row
